#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<pair<string, int>> v(n);
    for (auto& [name, score] : v) cin >> name >> score;
    sort(v.begin(), v.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    for (auto& [name, score] : v) cout << name << ' ' << score << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<pair<int, string>> v = {{-90, "yuna"}, {-75, "bora"}, {-90, "alex"}};
    sort(v.begin(), v.end());  // 점수(부호 반전) 오름차순, 같으면 이름 오름차순
    for (auto& [s, name] : v) cout << name << ' ' << -s << '\n';

    vector<string> w = {"kiwi", "fig", "apple", "date", "pear"};
    stable_sort(w.begin(), w.end(), [](const string& a, const string& b) {
        return a.size() < b.size();
    });
    for (auto& s : w) cout << s << ' ';
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> a = {1000000000, -5, 42, 42, 7};
    vector<int> xs = a;
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    for (int x : xs) cout << x << ' ';
    cout << '\n';
    for (int x : a) cout << lower_bound(xs.begin(), xs.end(), x) - xs.begin() << ' ';
    cout << '\n';
    return 0;
}
